&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;a href=&quot;https://wikimediafoundation.org/wiki/Our_projects&quot;&gt;&lt;strong&gt;Our Projects&lt;/strong&gt;&lt;/a&gt;&lt;/span&gt;&lt;/p&gt;
